package com.carteira.carteiraInvestimento.infrastructure.persistence;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="carteiras") public class CarteiraJpaEntity { @Id private UUID id; @Column(name="usuario_id",nullable=false,unique=true) private UUID usuarioId; @Column(nullable=false) private String nome; @Column(name="saldo_caixa_brl",nullable=false,precision=18,scale=2) private BigDecimal saldoCaixaBrl; @Column(name="data_criacao",nullable=false) private Instant dataCriacao; protected CarteiraJpaEntity(){} public CarteiraJpaEntity(UUID id,UUID usuarioId,String nome,BigDecimal saldo,Instant data){this.id=id;this.usuarioId=usuarioId;this.nome=nome;this.saldoCaixaBrl=saldo;this.dataCriacao=data;} public UUID getId(){return id;} public UUID getUsuarioId(){return usuarioId;} public String getNome(){return nome;} public BigDecimal getSaldoCaixaBrl(){return saldoCaixaBrl;} public Instant getDataCriacao(){return dataCriacao;} }
